// API Client for QualifyAI
import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:8000/api/v1';

export const submitApplicant = async (formData) => {
  return axios.post(`${API_BASE}/applicants/`, formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
};

export const fetchApplicant = async (id) => {
  return axios.get(`${API_BASE}/applicants/${id}`);
};

export const chatWithBot = async (question, applicantId) => {
  return axios.post(`${API_BASE}/chat/`, { question, applicant_id: applicantId });
};
